/**
 * Step 48 — validate live production (or staging) product URLs.
 *
 * Usage:
 *   node scripts/seo-validate-production.mjs
 *   SEO_VALIDATE_URL=https://anantafashion.com/products/foo node scripts/seo-validate-production.mjs
 *   SEO_VALIDATE_LIMIT=20 node scripts/seo-validate-production.mjs
 *
 * Reads SEO_PRODUCTION_URLS.txt from repo root (generated by api audit:seo).
 */
import assert from "node:assert/strict";
import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "../..");
const SITE = (process.env.SEO_TEST_ORIGIN || "https://anantafashion.com").replace(
  /\/$/,
  "",
);
const LIMIT = Number(process.env.SEO_VALIDATE_LIMIT || 10);
const SINGLE = process.env.SEO_VALIDATE_URL?.trim();

function jsonLdBlocks(html) {
  const blocks = [];
  const re = /<script type="application\/ld\+json">([\s\S]*?)<\/script>/gi;
  let m;
  while ((m = re.exec(html))) {
    try {
      blocks.push(JSON.parse(m[1]));
    } catch {
      /* ignore */
    }
  }
  return blocks;
}

function extractCanonical(html) {
  const m = html.match(/<link[^>]+rel="canonical"[^>]+href="([^"]+)"/i);
  return m?.[1] || null;
}

function extractTitle(html) {
  const m = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  return m?.[1]?.replace(/\s+/g, " ").trim() || "";
}

function extractMetaDescription(html) {
  const m = html.match(
    /<meta[^>]+name="description"[^>]+content="([^"]*)"/i,
  );
  return m?.[1]?.trim() || "";
}

async function validateUrl(url) {
  const issues = [];
  let res;
  try {
    res = await fetch(url, {
      redirect: "follow",
      headers: { Accept: "text/html", "User-Agent": "AnantaFashion-SEO-Audit/1.0" },
    });
  } catch (err) {
    return { url, ok: false, issues: [`Fetch failed: ${err.message}`] };
  }

  const html = await res.text();
  if (res.status !== 200) issues.push(`HTTP ${res.status}`);
  if (!/<h1[\s>]/i.test(html)) issues.push("Missing H1");
  if (!extractTitle(html)) issues.push("Missing title");
  if (!extractMetaDescription(html)) issues.push("Missing meta description");

  const canonical = extractCanonical(html);
  if (!canonical) issues.push("Missing canonical");
  else if (!canonical.startsWith("https://")) issues.push("Canonical not HTTPS");
  else if (canonical !== url.split("?")[0]) {
    issues.push(`Canonical mismatch: ${canonical}`);
  }

  const ld = jsonLdBlocks(html);
  if (!ld.some((n) => n["@type"] === "Product")) issues.push("Missing Product JSON-LD");
  if (!ld.some((n) => n["@type"] === "BreadcrumbList")) {
    issues.push("Missing BreadcrumbList JSON-LD");
  }

  const product = ld.find((n) => n["@type"] === "Product");
  if (product && !product.offers) issues.push("Product schema missing offers");

  return { url, ok: issues.length === 0, issues };
}

async function loadUrls() {
  if (SINGLE) return [SINGLE.startsWith("http") ? SINGLE : `${SITE}${SINGLE}`];
  const listPath = path.join(ROOT, "SEO_PRODUCTION_URLS.txt");
  try {
    const raw = await fs.readFile(listPath, "utf8");
    const urls = raw
      .split("\n")
      .map((l) => l.trim())
      .filter(Boolean);
    if (!urls.length) throw new Error("empty list");
    return urls.slice(0, LIMIT);
  } catch {
    return [`${SITE}/products/quilted-ladies-sling-bag`];
  }
}

const urls = await loadUrls();
console.log(`Validating ${urls.length} URL(s) on ${SITE}…\n`);

const results = [];
for (const url of urls) {
  const r = await validateUrl(url);
  results.push(r);
  const mark = r.ok ? "OK" : "FAIL";
  console.log(`${mark}  ${url}`);
  if (r.issues.length) console.log(`      ${r.issues.join("; ")}`);
}

const failed = results.filter((r) => !r.ok);
console.log(`\n${results.length - failed.length}/${results.length} passed`);

if (failed.length) {
  const report = [
    "# Production URL Validation Report",
    "",
    `Generated: ${new Date().toISOString()}`,
    "",
    `Site: ${SITE}`,
    "",
    "## Failures",
    "",
    ...failed.map(
      (r) => `- ${r.url}\n  - ${r.issues.join("\n  - ")}`,
    ),
    "",
    "## Pass",
    "",
    ...results
      .filter((r) => r.ok)
      .map((r) => `- ${r.url}`),
    "",
  ].join("\n");
  await fs.writeFile(path.join(ROOT, "SEO_PRODUCTION_VALIDATION_REPORT.md"), report);
  console.log("Wrote SEO_PRODUCTION_VALIDATION_REPORT.md");
  process.exitCode = 1;
} else {
  console.log("All checked URLs passed SEO validation.");
}
